      return '<div class="depthd"><span class="num">' + String(no).padStart(2, '0') + '</span>' + esc(deptName(+no)) + ' <span class="en">' + esc((DEPT[no] || {}).en) + '</span></div><div class="jdgrid">' +
        by[no].map(function (j) {
          var holders = S.data.emps.filter(function (e) { return e[2] === j.code; });
          var who = hitEmp[j.code] ? '<span style="color:var(--accent);font-weight:600">' + hitEmp[j.code].map(function (e) { return esc(e[1]); }).join('، ') + '</span>' : '';
          return '<a class="jdcard" href="#/jd/' + encodeURIComponent(j.code) + '"><span class="tt">' + esc(j.ar) + '</span><span class="en">' + esc(j.en) + '</span><span class="meta"><span class="tag">' + esc(j.code) + '</span><span>' + j.b.kpis.length + ' مؤشرات</span><span>·</span><span>' + holders.length + ' موظف</span></span>' + (who ? '<span class="meta">' + who + '</span>' : '') + '</a>';
        }).join('') + '</div>';
