function openEval(rec, admin) {
  var canEdit = rec.status !== 'signed' && (rec.ev.email === S.user.email || admin) && EMP[rec.emp.id];
  modal('<div class="mbox"><div class="mtool">' +
    '<button class="btn pri sm" id="mp">' + ic('print') + 'طباعة للتوقيع</button>' +
    (admin ? '<label class="f" style="flex-direction:row;align-items:center;gap:6px">الحالة <select class="inp" id="mst" style="width:auto;padding:4px 8px">' + STATUS.map(function (s) { return '<option value="' + s[0] + '"' + (s[0] === rec.status ? ' selected' : '') + '>' + s[1] + '</option>'; }).join('') + '</select></label>' : '') +
    (canEdit ? '<a class="btn sec sm" href="#/eval/' + encodeURIComponent(rec.id) + '">تعديل</a>' : '') +
    '<span class="grow"></span>' + (admin ? '<span id="mdel"><button class="btn danger sm" id="md">حذف</button></span>' : '') +
    '<button class="btn sec sm" data-close>إغلاق ✕</button><span class="msg" id="mm" style="width:100%"></span></div><div class="paperwrap">' + evalPaper(rec) + '</div></div>');
  $('#mp').onclick = function () {
    printPapers([evalPaper(rec)]);
    if (admin && rec.status === 'new') setEvalStatus(rec, 'printed');
  };
  if (admin) {
    if (!rec.read) { rec.read = true; api('markEval', { id: rec.id, read: true }).catch(function () {}); S.unread = Math.max(0, (S.unread || 1) - 1); updUnread(); var tr = $('[data-ev="' + rec.id + '"]'); if (tr) tr.classList.remove('unread'); }
    $('#mst').onchange = function () { setEvalStatus(rec, this.value); };
    $('#mdel').onclick = function (e) {
      if (e.target.id === 'md') { $('#mdel').innerHTML = '<span class="confirm">نقل إلى سلة المحذوفات؟ <button class="btn danger sm" id="my">نعم، احذف</button><button class="btn sec sm" id="mn">إلغاء</button></span>'; }
      if (e.target.id === 'mn') $('#mdel').innerHTML = '<button class="btn danger sm" id="md">حذف</button>';
      if (e.target.id === 'my') delEval(rec.id).then(function () { closeModal(); route(); }).catch(function (er) { $('#mm').className = 'msg err'; $('#mm').textContent = er.message; });
    };
  }
}
function setEvalStatus(rec, s) {
  rec.status = s; api('markEval', { id: rec.id, status: s }).then(function () { toast('الحالة: ' + STAT[s][1]); var st = $('#mst'); if (st) st.value = s; if (location.hash.indexOf('inbox') >= 0) drawInbox(); }).catch(function (e) { toast(e.message); });
}
function updUnread() { var u = $('#unread'); if (u) { u.textContent = S.unread; u.hidden = !S.unread; } }

/* ----- admin: inbox */
var IF = { q: '', dept: '', rate: '', stat: '', per: '' };
VIEWS.inbox = function (v) {
  v.innerHTML = head('صندوق النتائج', 'كل التقييمات الواردة من رؤساء الأقسام — اضغط على أي تقييم لعرضه وطباعته', '', '<button class="btn sec" id="rf">تحديث</button><button class="btn sec" id="trs">' + ic('trash') + 'سلة المحذوفات</button><button class="btn sec" id="csv">' + ic('dl') + 'تصدير Excel</button><button class="btn pri" id="pa">' + ic('print') + 'طباعة المعروض</button>') + '<div id="ibx"><div class="loading" style="min-height:30vh"><div class="spin"></div></div></div>';
  var load = function () { return api('listEvals').then(function (r) { S.inbox = r.evals; S.unread = r.evals.filter(function (x) { return !x.read; }).length; updUnread(); drawInbox(); }).catch(function (e) { $('#ibx').innerHTML = '<div class="empty">' + esc(e.message) + '</div>'; }); };
  $('#rf').onclick = load;
  $('#trs').onclick = function () { trashModal(load); };
  $('#csv').onclick = function () { exportCSV(filteredInbox()); };
  $('#pa').onclick = function () { var l = filteredInbox(); if (!l.length) return toast('لا توجد تقييمات للطباعة'); printPapers(l.map(evalPaper)); };
  if (S.inbox) drawInbox(); load();
};
function filteredInbox() {
  var q = IF.q.trim().toLowerCase();
  return (S.inbox || []).filter(function (r) {
    return (!IF.dept || String(r.emp.dept) === IF.dept) && (IF.rate === '' || String(r.r) === IF.rate) && (IF.stat === 'arch' ? r.archived : (!r.archived && (!IF.stat || r.status === IF.stat))) && (!IF.per || r.period === IF.per) &&
      (!q || (r.emp.name + ' ' + r.emp.id + ' ' + r.emp.code + ' ' + r.ev.name + ' ' + r.ev.email).toLowerCase().indexOf(q) >= 0);
  });
}
function drawInbox() {
  var box = $('#ibx'); if (!box) return;
  var all = S.inbox || [], list = filteredInbox();
  var pers = all.map(function (r) { return r.period; }).filter(function (p, i, a) { return a.indexOf(p) === i; }).sort().reverse();
  var cnt = [0, 0, 0, 0]; all.forEach(function (r) { cnt[r.r]++; });
  var uniq = {}; all.forEach(function (r) { uniq[r.emp.id] = 1; });
  var avg = all.length ? all.reduce(function (s, r) { return s + r.F; }, 0) / all.length : null;
  var heads = {}; all.forEach(function (r) { heads[r.ev.email] = 1; });
  var opt = function (val, cur, label) { return '<option value="' + esc(val) + '"' + (String(cur) === String(val) ? ' selected' : '') + '>' + label + '</option>'; };
  box.innerHTML = '<div class="kpis">' + kpiTile(all.length, 'تقييم وارد · Received', true) + kpiTile(S.unread || 0, 'غير مقروء · Unread') + kpiTile(Object.keys(uniq).length + '<span class="muted" style="font-size:14px"> / ' + S.data.emps.length + '</span>', 'موظفون مُقيَّمون') + kpiTile(avg == null ? '—' : avg.toFixed(1), 'متوسط الدرجة') + kpiTile(Object.keys(heads).length, 'مقيِّمون أرسلوا') + kpiTile(all.filter(function (r) { return r.status !== 'signed'; }).length, 'بانتظار التوقيع') + '</div>' +
    '<div class="cols2" style="margin:16px 0"><div class="card"><div class="hd"><h2>التغطية حسب القسم</h2></div><div class="bd bars" style="max-height:260px;overflow:auto">' + S.data.depts.map(function (d) {
      var tot = S.data.emps.filter(function (e) { return empDept(e) === d.no; }).length, n = {}; all.forEach(function (r) { if (r.emp.dept === d.no) n[r.emp.id] = 1; }); var k = Object.keys(n).length;
      return tot ? '<div class="bar" style="grid-template-columns:140px minmax(0,1fr) 54px"><span>' + esc(d.ar) + '</span><div class="track"><div class="fill" style="width:' + k / tot * 100 + '%"></div></div><span class="num">' + k + '/' + tot + '</span></div>' : '';
    }).join('') + '</div></div><div class="card"><div class="hd"><h2>توزيع التقديرات</h2></div><div class="bd bars">' + [3, 2, 1, 0].map(function (i) { var mx = Math.max.apply(null, cnt.concat(1)); return '<div class="bar" style="grid-template-columns:96px minmax(0,1fr) 40px"><span class="pill r' + i + '">' + RATES[i][0] + '</span><div class="track" style="height:12px"><div class="fill" style="width:' + cnt[i] / mx * 100 + '%"></div></div><span class="num">' + cnt[i] + '</span></div>'; }).join('') + '<div class="muted" style="font-size:11.5px">ممتاز ≥ 85 · جيد 70–84.9 · متوسط 55–69.9 · ضعيف &lt; 55</div></div></div></div>' +
    '<div class="card" style="margin-bottom:12px"><div class="bd sbox">' +
    '<label class="f">بحث <span class="en">Search</span><input class="inp" id="iq" type="search" value="' + esc(IF.q) + '"></label>' +
    '<label class="f">القسم<select class="inp" id="id">' + opt('', IF.dept, 'الكل') + S.data.depts.map(function (d) { return opt(d.no, IF.dept, esc(d.ar)); }).join('') + '</select></label>' +
    '<label class="f">التقدير<select class="inp" id="ir">' + opt('', IF.rate, 'الكل') + RATES.map(function (r, i) { return opt(i, IF.rate, r[0]); }).join('') + '</select></label>' +
    '<label class="f">الحالة<select class="inp" id="is">' + opt('', IF.stat, 'الكل') + STATUS.map(function (s) { return opt(s[0], IF.stat, s[1]); }).join('') + opt('arch', IF.stat, 'المؤرشفة') + '</select></label>' +
    '<label class="f">الفترة<select class="inp" id="ip">' + opt('', IF.per, 'الكل') + pers.map(function (p) { return opt(p, IF.per, esc(p)); }).join('') + '</select></label></div></div>' +
    '<div class="muted" style="font-size:12px;margin-bottom:6px">' + list.length + ' من ' + all.length + '</div><div id="itb">' + (all.length ? evalTable(list, true) : '<div class="empty">لم تصل تقييمات بعد. أضف رؤساء الأقسام من صفحة «المستخدمون والأقسام» وأرسل لهم رمز التفعيل.</div>') + '</div>';
  [['iq', 'q', 'input'], ['id', 'dept', 'change'], ['ir', 'rate', 'change'], ['is', 'stat', 'change'], ['ip', 'per', 'change']].forEach(function (x) {
    $('#' + x[0]).addEventListener(x[2], function () { IF[x[1]] = this.value; var l = filteredInbox(); $('#itb').innerHTML = evalTable(l, true); });
  });
  $('#itb').onclick = function (e) {
    if (evalActs(e, drawInbox)) return;
    var r = e.target.closest('[data-ev]'); if (!r) return; var rec = (S.inbox || []).filter(function (x) { return x.id === r.dataset.ev; })[0]; if (rec) openEval(rec, true); };
}
function trashModal(reload) {
  var m = modal('<div class="mbox"><div class="card"><div class="hd"><h2>سلة المحذوفات</h2><span class="muted" style="font-size:12px">التقييمات المحذوفة — استرجعها أو احذفها نهائياً</span></div><div class="bd" id="tbx"><div class="loading" style="min-height:20vh"><div class="spin"></div></div></div><div class="bd" style="display:flex;gap:8px;justify-content:space-between;padding-top:0"><span id="tall"></span><button class="btn sec" data-close>إغلاق</button></div></div></div>');
  var list = [];
  var draw = function () {
    var b = $('#tbx'); if (!b) return;
    $('#tall').innerHTML = list.length ? '<button class="btn danger sm" id="tpa">إفراغ السلة</button>' : '';
    b.innerHTML = !list.length ? '<div class="empty">السلة فارغة</div>' : '<div class="tw"><table class="t minw"><thead><tr><th>حُذف في</th><th>الموظف</th><th>المقيِّم</th><th>النوع / الفترة</th><th>النهائية</th><th></th></tr></thead><tbody>' +
      list.map(function (r) {
        return '<tr><td class="num" style="font-size:12px">' + esc(String(r.deleted || '').slice(0, 16)) + '</td><td>' + esc(r.emp.name) + '<div class="num muted" style="font-size:11px">' + esc(r.emp.id) + '</div></td><td>' + esc(r.ev.name) + '</td><td>' + (TYPE[r.type] ? TYPE[r.type][1] : esc(r.type)) + '<div class="num muted" style="font-size:11px">' + esc(r.period) + '</div></td><td class="num"><b>' + Number(r.F).toFixed(1) + '</b></td>' +
          '<td class="w"><div class="actions"><button class="btn pri sm" data-rs="' + esc(r.id) + '">استرجاع</button><button class="btn danger sm" data-pg="' + esc(r.id) + '">حذف نهائي</button></div></td></tr>';
      }).join('') + '</tbody></table></div>';
  };
  var load = function () { return api('listTrash').then(function (r) { list = r.evals; draw(); }).catch(function (e) { var b = $('#tbx'); if (b) b.innerHTML = '<div class="empty">' + esc(e.message) + '</div>'; }); };
  m.addEventListener('click', function (e) {
    var t = e.target.closest('button'); if (!t) return;
    if (t.dataset.rs) api('restoreEval', { id: t.dataset.rs }).then(function (res) { if (res.eval && res.eval.ev && res.eval.ev.email === S.user.email) { dropMine(res.eval.id); S.evals.unshift(res.eval); var mc = $('#minec'); if (mc) mc.textContent = S.evals.length; } toast('تم استرجاع التقييم إلى صندوق النتائج'); load(); if (reload) reload(); }).catch(function (er) { toast(er.message); });
    if (t.dataset.pg) { if (t.dataset.ok) api('purgeEval', { id: t.dataset.pg }).then(function () { toast('حُذف نهائياً'); load(); }).catch(function (er) { toast(er.message); }); else { t.dataset.ok = '1'; t.textContent = 'تأكيد الحذف النهائي'; } }
    if (t.id === 'tpa') { if (t.dataset.ok) api('purgeEval', { id: '*' }).then(function () { toast('تم إفراغ السلة'); load(); }).catch(function (er) { toast(er.message); }); else { t.dataset.ok = '1'; t.textContent = 'تأكيد: حذف الكل نهائياً'; } }
  });
  load();
}
function exportCSV(list) {
  var q = function (v) { return '"' + String(v == null ? '' : v).replace(/"/g, '""') + '"'; };
  var hd = ['Date التاريخ', 'Employee ID الرقم', 'Name الاسم', 'Job Code', 'Job Title المسمى', 'Department القسم', 'Evaluator المقيم', 'Evaluator e-mail', 'Type النوع', 'Period الفترة', 'Section A', 'Section B', 'Final النهائية', 'Rating التقدير', 'Recommendations التوصيات', 'Status الحالة'];
  var rows = list.map(function (r) { var j = JOB[r.emp.code] || {}; return [r.updated, r.emp.id, r.emp.name, r.emp.code, (j.ar || '') + ' / ' + (j.en || ''), deptName(r.emp.dept), r.ev.name, r.ev.email, TYPE[r.type][2], r.period, r.A, r.B, r.F, RATES[r.r][1] + ' / ' + RATES[r.r][0], r.rc.map(function (k) { return REC[k][1]; }).join('; '), STAT[r.status][2]].map(q).join(','); });
  if (window.LO_SAVE) return window.LO_SAVE('L-O_Evaluations_' + new Date().toISOString().slice(0, 10) + '.csv', '\uFEFF' + [hd.map(q).join(',')].concat(rows).join('\r\n'));
  var blob = new Blob(['﻿' + [hd.map(q).join(',')].concat(rows).join('\r\n')], { type: 'text/csv;charset=utf-8' });
  var a = document.createElement('a'); a.href = URL.createObjectURL(blob); a.download = 'L-O_Evaluations_' + new Date().toISOString().slice(0, 10) + '.csv';
  document.body.appendChild(a); a.click(); setTimeout(function () { URL.revokeObjectURL(a.href); a.remove(); }, 500);
}

